from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];html=(R/'dist/INK-Street-Fighter-6.html').read_bytes();O=R/'qa/air-pursuit'
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1000});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKPursuitLab?.ready');p.evaluate("()=>INKDuel.start('training')")
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,rows=[],check=(name,passed)=>rows.push({name,passed});A.start('ken','ryu','training','classic',33);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;A.teleport(0,560);A.teleport(1,710);A.tryMove(0,'cHP');for(let n=0;n<60&&!A.fighters[0]._inkLaunch;n++)A.step();const f=A.fighters[0],paid=f.drive;G.paused=false;A.press(0,'right');A.press(0,'RUSH');A.release(0,'RUSH');A.release(0,'right');G.paused=true;check('Forward F during real launch hitstop queues AIR_CHASE',G.hitstop>0&&f.input.queue[0]?.m.id==='AIR_CHASE');for(let n=0;n<40&&!f._inkPursuit;n++)A.step();check('Buffered forward F uses paid pursuit after freeze',f._inkPursuit?.phase==='windup'&&Math.abs(paid-f.drive-1.5)<.02);for(let n=0;n<10&&!(f._inkPursuit?.phase==='flight'&&f._inkPursuit.age>=2);n++)A.step();G.paused=false;A.press(0,'MP');A.release(0,'MP');G.paused=true;A.step(3);check('K button selects actual pursuit air normal',f.attack?.m.id==='aMP'&&f.attack.m.pursuitAir);const state=JSON.stringify([f.x,f.y,f.hp,f.drive,f._inkPursuit,A.geometry(f)]);A.renderFraction(1);const dom=document.getElementById('game').innerHTML;for(let n=0;n<8;n++)A.renderFraction(1);check('Pursuit render is deterministic and simulation read-only',dom===document.getElementById('game').innerHTML&&state===JSON.stringify([f.x,f.y,f.hp,f.drive,f._inkPursuit,A.geometry(f)]));for(let n=0;n<60&&!f.attack?.hitConfirmed;n++)A.step();A.renderFraction(1);return rows;}''')
 p.locator('#game').screenshot(path=str(O/'pursuit-hit.png'))
 rows+=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,rows=[],check=(name,passed)=>rows.push({name,passed});for(const disabled of [false,true]){A.start('ryu','ken','training','classic',34);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;A.teleport(0,560);A.teleport(1,710);A.tryMove(0,'cHP');for(let n=0;n<60&&!A.fighters[0]._inkLaunch;n++)A.step();while(G.hitstop)A.step();const f=A.fighters[0];if(disabled)INK.AirPursuit.settings.enabled=false;else while(G.actionTick-f._inkLaunch.at<=8)A.step();const allowed=A.decide(0,'RUSH').ok;G.paused=false;A.press(0,'right');A.press(0,'RUSH');A.release(0,'RUSH');A.release(0,'right');G.paused=true;check((disabled?'Disabled':'Expired')+' pursuit keeps existing forward F rush cancel',allowed&&f.state==='rush'&&!f._inkPursuit);INK.AirPursuit.settings.enabled=true;}return rows;}''')
 p.locator('#pursuit-practice').click();p.evaluate('SVG_FIGHTER.state.paused=true');rows.append({'name':'Practice button creates actual cHP request','passed':p.evaluate("SVG_FIGHTER.fighters[0].attack?.m.id==='cHP'")});b.close()
report={'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors};(O/'controls.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2));assert not errors and all(r['passed'] for r in rows)
